// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/auth/login", wrapper.Login)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/auth/logout", wrapper.Logout)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/auth/register", wrapper.Register)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/events", wrapper.GetPublicEvents)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/health/live", wrapper.GetHealthLive)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/health/ready", wrapper.GetHealthReady)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/me", wrapper.GetMe)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/me/current", wrapper.GetCurrentRental)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/me/events", wrapper.GetPrivateEvents)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/me/notifications", wrapper.GetNotifications)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/me/notifications/{id}/read", wrapper.ReadNotification)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/reservations", wrapper.Reserve)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/reservations/{id}/cancel", wrapper.CancelRental)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/reservations/{id}/start", wrapper.StartRental)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/rides/{id}/pause", wrapper.PauseRental)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/rides/{id}/resume", wrapper.ResumeRental)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/tariffs", wrapper.GetTariffs)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/vehicles", wrapper.GetVehicles)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/vehicles/{id}", wrapper.GetVehicle)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/zones", wrapper.GetZones)
	})

	return r
}

